(function(){'use strict';var calApi=null;var calLoading=null;function getCalApi(){if(calApi){return Promise.resolve(calApi)}
if(typeof window.Cal==='function'){calApi=window.Cal('init','cal_core');return Promise.resolve(calApi)}
if(calLoading){return calLoading}
calLoading=new Promise(function(resolve,reject){var script=document.querySelector('script[src*="cal.com/embed.js"]');if(script){script.addEventListener('load',load);script.addEventListener('error',reject)}else{script=document.createElement('script');script.src='https://cal.com/embed.js';script.async=!0;script.onload=load;script.onerror=reject;document.head.appendChild(script)}
function load(){if(typeof window.Cal!=='function'){reject(new Error('Cal.com API unavailable.'));return}
calApi=window.Cal('init','cal_core');resolve(calApi)}});return calLoading}
function initButton(button){if(!button||button.dataset.calInitialized){return}
var calUrl=button.dataset.url;if(!calUrl){return}
button.dataset.calInitialized='true';getCalApi().then(function(api){button.addEventListener('click',function(event){event.preventDefault();api('modal',{calLink:calUrl})})}).catch(function(error){button.dataset.calInitialized='';console.error('Cal.com:',error)})}
function showPrompt(prompt){if(!prompt){return}
prompt.style.display='block';var button=prompt.querySelector('#calcom-embed-link, .calcom-embed-link');initButton(button)}
document.addEventListener('wpcf7mailsent',function(event){var form=event.target;if(!form){return}
setTimeout(function(){var prompt=form.querySelector('.calcom-cf7-prompt');var response=form.querySelector('.wpcf7-response-output');if(!prompt||!response){return}
response.appendChild(prompt);prompt.style.display='block';if(window.calcomData){return}
initButton(prompt)},100)});if(window.jQuery){jQuery(document).on('wpformsAjaxSubmitSuccess',function(){setTimeout(function(){document.querySelectorAll('.calcom-wpforms-prompt').forEach(showPrompt)},100)})}
document.addEventListener('fluentform_submission_success',function(){setTimeout(function(){document.querySelectorAll('.calcom-fluentforms-prompt').forEach(showPrompt)},100)})})()